    return { exampleCode: code, expectedOutput: name === 'if' ? 'Adult' : name === 'foreach' ? 'HTML\nCSS' : name === 'function' ? 'Hello, Ada!' : name === 'class' ? 'No direct output.' : 'Example', usageDescription: description, language: skill === 'laravel' ? 'PHP / Laravel' : skill.includes('wordpress') ? 'PHP / WordPress' : 'PHP', previewType: 'none' as const }
