    const code = commands[name] || (name === '|' ? 'cat app.log | grep "error"' : name === '>' ? 'printf "ready\\n" > status.txt' : name === '>>' ? 'printf "done\\n" >> status.txt' : name === '&&' ? 'mkdir app && cd app' : name === 'export' ? 'export APP_ENV=production' : 'printf "ready\\n"')
