export const syntaxSkills = skillGroups.flatMap((group) => group.skills.map((skill) => ({ slug: skillSlug(skill.name), name: skill.name }))).filter((skill, index, all) => all.findIndex((item) => item.slug === skill.slug) === index)
const missingCatalogs = syntaxSkills.filter((skill) => !bySlug[skill.slug])
if (missingCatalogs.length > 0) throw new Error(`Missing syntax reference catalog: ${missingCatalogs.map((skill) => skill.name).join(', ')}`)

export const syntaxReference: SyntaxReferenceItem[] = syntaxSkills.flatMap((skill) => bySlug[skill.slug]!.map(([name, description, category], index) => {
  const rawExample = exactExamples[`${skill.slug}:${name}`] ?? generatedExample(skill.slug, name, description)
  const example = (skill.slug === 'css3' || skill.slug === 'responsive-web-design') && rawExample.language === 'CSS'
    ? { ...rawExample, exampleCode: `<p class="demo-text">Example paragraph</p>\n<style>\n${rawExample.exampleCode}\n</style>`, language: 'HTML + CSS' }
    : rawExample
  return { id: `${skill.slug}:${name}:${index}`, skillSlug: skill.slug, skillName: skill.name, category, name, description, ...example, typeCheckResult: skill.slug === 'typescript' ? (example.typeCheckResult ?? 'Valid TypeScript syntax for this example; type-only declarations are erased at runtime.') : example.typeCheckResult, sortOrder: index }
}))
